<?php $title='Dienstbuch '.$date; ?>
<div class="document-header"><div><strong>WKS · Tagesdienstbuch</strong><div><?= e($day['location_name']??'Standort') ?></div></div><div><strong><?= e((new DateTimeImmutable($date))->format('d.m.Y')) ?></strong><div><?= e($date.'_Dienstbuch_'.($day['location_name']??'')) ?></div></div></div>
<?php foreach($entries as $entry):?><article class="print-entry"><div class="print-meta"><?= e(date('H:i',strtotime($entry['occurred_at']))) ?> · <?= e($entry['shift_name']??'–') ?> · <?= e($entry['event_type_name']??'Automatisch') ?> · <?= e($entry['status']) ?></div><strong><?= e($entry['category_name']??'') ?></strong><div class="prose"><?= e($entry['facts']) ?></div><?php if($entry['measures_text']):?><div><b>Maßnahmen:</b> <?= e($entry['measures_text']) ?></div><?php endif;?><?php if($entry['result_text']):?><div><b>Ergebnis:</b> <?= e($entry['result_text']) ?></div><?php endif;?></article><?php endforeach;?>
